INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5464179, 784713, 50695, '<td valign="top">I like how the subject encroaches, almost destroying the image.</td>', 'I like how the subject encroaches, almost destroying the image.', '2009-05-02 17:40:57.000000', NULL, 1),
(5464180, 785571, 50695, '<td valign="top">great composition. far too subtle for dpc, but to simply look at it and not think about what it is leads to great pleasure for the viewer.</td>', 'great composition. far too subtle for dpc, but to simply look at it and not think about what it is leads to great pleasure for the viewer.', '2009-05-02 17:41:34.000000', NULL, 1),
(5464181, 784465, 50695, '<td valign="top">great capture.</td>', 'great capture.', '2009-05-02 17:41:42.000000', NULL, 1),
