(5464183, 785120, 50695, '<td valign="top">good lighting and processing.</td>', 'good lighting and processing.', '2009-05-02 17:42:02.000000', NULL, 1),
(5464184, 785644, 50695, '<td valign="top">funny disorienting capture. I like it.</td>', 'funny disorienting capture. I like it.', '2009-05-02 17:42:23.000000', NULL, 1),
(5464387, 785499, 83313, '<td valign="top">Really grainy and soft. Looks like an extreme crop. Photographing a bird in flight can be hard, as you have found!</td>', 'Really grainy and soft. Looks like an extreme crop. Photographing a bird in flight can be hard, as you have found!', '2009-05-02 20:07:17.000000', NULL, 1),
(5464389, 784871, 83313, '<td valign="top">A nice catch of the bird in flight. Only real problem is that tree in the middle of the frame that grabs my eye instead of the bird.</td>', 'A nice catch of the bird in flight. Only real problem is that tree in the middle of the frame that grabs my eye instead of the bird.', '2009-05-02 20:08:38.000000', NULL, 1),
(5464390, 785566, 83313, '<td valign="top">One of my kids used to do this when she was a baby!</td>', 'One of my kids used to do this when she was a baby!', '2009-05-02 20:09:07.000000', NULL, 1),
(5464391, 785123, 83313, '<td valign="top">Almost a killer shot. Not totally sure what it is missing. Maybe it''s something in the details. Wish I could be a little more specific for you.</td>', 'Almost a killer shot. Not totally sure what it is missing. Maybe it''s something in the details. Wish I could be a little more specific for you.', '2009-05-02 20:11:10.000000', NULL, 1),
(5464392, 785485, 83313, '<td valign="top">Fantastic in flight catch of this guy.The bird himself seems a little grainy, but you probably had a tough time choosing between smoothness and preserving detail.  Better than I could do, and still deserves a good vote for what you achieved.</td>', 'Fantastic in flight catch of this guy.The bird himself seems a little grainy, but you probably had a tough time choosing between smoothness and preserving detail.  Better than I could do, and still deserves a good vote for what you achieved.', '2009-05-02 20:13:10.000000', NULL, 1),
(5464395, 785443, 83313, '<td valign="top">I like the slight backlighting of the wings. Not a lot of wow factor other than that, though. Birds in flight are hard to to.</td>', 'I like the slight backlighting of the wings. Not a lot of wow factor other than that, though. Birds in flight are hard to to.', '2009-05-02 20:14:40.000000', NULL, 1),
(5464510, 785485, 66616, '<td valign="top">excellent</td>', 'excellent', '2009-05-02 22:05:59.000000', NULL, 1),
