(5464567, 785442, 66616, '<td valign="top">nice work</td>', 'nice work', '2009-05-02 22:22:37.000000', NULL, 1),
(5464834, 785477, 88247, '<td valign="top">A perfect 10!! What a great capture,well done And, Good luck:-)</td>', 'A perfect 10!! What a great capture,well done And, Good luck:-)', '2009-05-03 03:18:03.000000', NULL, 1),
(5464835, 785120, 57775, '<td valign="top">Beautiful horse and beautiful lighting!  9</td>', 'Beautiful horse and beautiful lighting!  9', '2009-05-03 03:23:18.000000', NULL, 1),
(5464884, 785054, 47487, '<td valign="top">I really, really like this. It''s very much out of the DPC box and I hope you''re not getting slammed for that but even if you are, take heart. This is a beautiful, evocative image. I can almost hear their whirring wings.</td>', 'I really, really like this. It''s very much out of the DPC box and I hope you''re not getting slammed for that but even if you are, take heart. This is a beautiful, evocative image. I can almost hear their whirring wings.', '2009-05-03 05:05:05.000000', NULL, 1),
(5464886, 785457, 47487, '<td valign="top">Heh. Brilliant. REALLY well-done.</td>', 'Heh. Brilliant. REALLY well-done.', '2009-05-03 05:05:57.000000', NULL, 1),
(5464887, 784522, 47487, '<td valign="top">LOL! Classic. Well-captured, too.</td>', 'LOL! Classic. Well-captured, too.', '2009-05-03 05:06:38.000000', NULL, 1),
(5464888, 785263, 47487, '<td valign="top">Ooh, purty. Maybe a tiny bit overprocessed around the wings, but lovely.</td>', 'Ooh, purty. Maybe a tiny bit overprocessed around the wings, but lovely.', '2009-05-03 05:07:15.000000', NULL, 1),
(5465118, 785265, 39850, '<td valign="top">9 - Excellent capture and clarity.  I like the unusual composition, especially with the subtle trees in the background and the good texture on the grass.</td>', '9 - Excellent capture and clarity.  I like the unusual composition, especially with the subtle trees in the background and the good texture on the grass.', '2009-05-03 10:04:21.000000', NULL, 1),
(5465120, 785120, 39850, '<td valign="top">8 - That''s a lot of grooming there.  What a knock-out.  Tones suit this very well, especially with the added backlit element.</td>', '8 - That''s a lot of grooming there.  What a knock-out.  Tones suit this very well, especially with the added backlit element.', '2009-05-03 10:05:27.000000', NULL, 1),
(5465123, 784770, 39850, '<td valign="top">8 - Like the intensity captured, nice rich colorings too.</td>', '8 - Like the intensity captured, nice rich colorings too.', '2009-05-03 10:05:51.000000', NULL, 1),
(5465124, 785293, 39850, '<td valign="top">8 - Good intensity and clarity.</td>', '8 - Good intensity and clarity.', '2009-05-03 10:06:10.000000', NULL, 1),
(5465125, 784522, 39850, '<td valign="top">8 - Nice colors and capture.</td>', '8 - Nice colors and capture.', '2009-05-03 10:06:23.000000', NULL, 1),
(5465126, 784654, 39850, '<td valign="top">8 - Good clarity and I like the unusual angle.</td>', '8 - Good clarity and I like the unusual angle.', '2009-05-03 10:06:43.000000', NULL, 1),
