(5472307, 784654, 97852, '<td valign="top">Congrats on the blue!  Great Shot!  I had it ranked in my top group and was happy to see it get top honors.  Way to go!</td>', 'Congrats on the blue!  Great Shot!  I had it ranked in my top group and was happy to see it get top honors.  Way to go!', '2009-05-06 10:30:39.000000', NULL, 0),
